// Keeps the read-transform fixtures small (they are git-ignored, regenerated by capture-all.sh):
// every fixture whose calls exceed RS_READ_MAX_CALL_BYTES (default 1.5 MB) keeps a subset that
// prioritises structural coverage: first one call per distinct signature (context, fields,
// table, error class, and the set of key paths of data and output, with array indices collapsed),
// then evenly strided calls until the byte budget is used. Kept calls stay in recorded order.
// Run the TZ replays (capture/replay.ts) afterwards: overlays reference call indexes.
//   node test/__rs/read/capture/prune.mjs [--stamp-time-zone <IANA zone for files without one>]
import crypto from 'crypto'
import fs from 'fs'
import path from 'path'

const fixturesDir = path.resolve(import.meta.dirname, '../fixtures')
const budget = Number(process.env.RS_READ_MAX_CALL_BYTES ?? 1_500_000)
const stampIndex = process.argv.indexOf('--stamp-time-zone')
const stampZone = stampIndex === -1 ? undefined : process.argv[stampIndex + 1]

const keyPaths = (value, prefix, out) => {
  if (Array.isArray(value)) {
    for (const item of value) {
      keyPaths(item, `${prefix}[]`, out)
    }
  } else if (value && typeof value === 'object') {
    for (const [key, inner] of Object.entries(value)) {
      const next = `${prefix}.${key}`
      out.add(next)
      keyPaths(inner, next, out)
    }
  }
  return out
}

const signature = (call) => {
  const paths = [
    ...keyPaths(call.data, 'd', new Set()),
    ...keyPaths(call.output ?? null, 'o', new Set()),
  ]
  const head = [call.context, call.fields, call.tableName, call.error?.name ?? '']
  return crypto
    .createHash('sha1')
    .update(JSON.stringify([head, paths.sort()]))
    .digest('hex')
}

for (const sub of ['', 'schema-linked']) {
  const dir = path.join(fixturesDir, sub)
  if (!fs.existsSync(dir)) {
    continue
  }
  for (const file of fs
    .readdirSync(dir)
    .filter((f) => f.endsWith('.json'))
    .sort()) {
    const full = path.join(dir, file)
    const fixture = JSON.parse(fs.readFileSync(full, 'utf8'))
    let changed = false
    if (!fixture.timeZone && stampZone) {
      fixture.timeZone = stampZone
      changed = true
    }
    const sizes = fixture.calls.map((call) => JSON.stringify(call).length)
    const totalBytes = sizes.reduce((a, b) => a + b, 0)
    if (totalBytes > budget) {
      const keep = new Set()
      let used = 0
      const seen = new Set()
      fixture.calls.forEach((call, i) => {
        const sig = signature(call)
        if (!seen.has(sig) && used + sizes[i] <= budget) {
          seen.add(sig)
          keep.add(i)
          used += sizes[i]
        }
      })
      const remaining = fixture.calls.map((_, i) => i).filter((i) => !keep.has(i))
      const stride = Math.max(
        1,
        Math.ceil(remaining.reduce((a, i) => a + sizes[i], 0) / Math.max(1, budget - used)),
      )
      for (let offset = 0; offset < stride; offset++) {
        for (let j = offset; j < remaining.length; j += stride) {
          const i = remaining[j]
          if (!keep.has(i) && used + sizes[i] <= budget) {
            keep.add(i)
            used += sizes[i]
          }
        }
      }
      const before = fixture.calls.length
      fixture.calls = fixture.calls.filter((_, i) => keep.has(i))
      console.log(
        `${path.join(sub, file)}: kept ${fixture.calls.length}/${before} calls (${seen.size} signatures), ${used} bytes`,
      )
      changed = true
    }
    if (changed) {
      const { version, name, timeZone, ...rest } = fixture
      fs.writeFileSync(full, JSON.stringify({ version, name, timeZone, ...rest }))
    }
  }
}
